  archive:'<rect x="3" y="3" width="18" height="4" rx="1"/><path d="M5 7v13a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1V7M10 12h4"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="m19.4 15 1.2 2-2.1 2.1-2-1.2a7 7 0 0 1-2 1v2.3h-3V19a7 7 0 0 1-2-1l-2 1.2-2.1-2.1 1.2-2a7 7 0 0 1-1-2H3v-3h2.4a7 7 0 0 1 1-2l-1.2-2 2.1-2.1 2 1.2a7 7 0 0 1 2-1V2h3v2.4a7 7 0 0 1 2 1l2-1.2 2.1 2.1-1.2 2a7 7 0 0 1 1 2H22v3h-2.4a7 7 0 0 1-1.2 1.7z"/>',
  plus:'<path d="M12 5v14M5 12h14"/>', minus:'<path d="M5 12h14"/>',
